<section class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 class="text-2xl font-bold text-slate-900">Laporan Pelanggan</h1><p class="mt-1 text-sm text-slate-500">Rekap status, tindakan pemutusan, dan daftar ulang pelanggan.</p></div><a href="<?= e(url('/laporan/print?' . http_build_query($filters))) ?>" target="_blank" rel="noopener" class="inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-900/15 hover:bg-primary-dark">▣ Cetak Laporan</a></section>
<section class="rounded-2xl bg-white p-4 shadow-card sm:p-6"><form method="get" class="grid gap-3 md:grid-cols-2 xl:grid-cols-5"><div><label class="form-label" for="periode">Dibuat sejak</label><input id="periode" type="date" name="periode" value="<?= e($filters['periode']) ?>" class="form-input"></div><div><label class="form-label" for="status">Status pelanggan</label><select id="status" name="status" class="form-input"><option value="">Semua status</option><?php foreach (['Aktif','Nonaktif','Putus'] as $option): ?><option <?= $filters['status'] === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><div><label class="form-label" for="jenis">Jenis tindakan</label><select id="jenis" name="jenis" class="form-input"><option value="">Semua tindakan</option><?php foreach (['Angkat Meter','Potong Pipa Dinas','Tutup Lubang Bor'] as $option): ?><option <?= $filters['jenis'] === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><div><label class="form-label" for="verifikasi">Status daftar ulang</label><select id="verifikasi" name="verifikasi" class="form-input"><option value="">Semua status</option><?php foreach (['Pending','Disetujui','Ditolak'] as $option): ?><option <?= $filters['verifikasi'] === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><div class="flex items-end gap-2"><button class="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white">Cari</button><a href="<?= e(url('/laporan')) ?>" class="rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-600">Reset</a></div></form><div class="mt-6 overflow-hidden rounded-xl border border-slate-100"><?php if ($rows): ?><div class="table-wrap"><table class="w-full min-w-[1120px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">NPA / Pelanggan</th><th class="px-5 py-3">Alamat</th><th class="px-5 py-3">Status</th><th class="px-5 py-3">Lama Nonaktif</th><th class="px-5 py-3">Tindakan</th><th class="px-5 py-3">Biaya Tindakan</th><th class="px-5 py-3">Daftar Ulang</th><th class="px-5 py-3">Biaya D.U.</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($rows as $row): $kategori = kategoriStatus($row); ?><tr><td class="px-5 py-4"><a href="<?= e(url('/pelanggan/' . rawurlencode($row['npa']))) ?>" class="font-semibold text-slate-800 hover:text-primary"><?= e($row['nama_pelanggan']) ?></a><p class="mt-1 font-mono text-xs text-primary"><?= e($row['npa']) ?></p></td><td class="max-w-xs px-5 py-4 text-slate-600"><?= e($row['alamat']) ?></td><td class="px-5 py-4"><span class="badge badge-<?= $kategori['key'] === 'aktif' ? 'disetujui' : ($kategori['key'] === 'nonaktif_lama' ? 'ditolak' : 'pending') ?>"><?= e($kategori['label']) ?></span></td><td class="px-5 py-4 text-slate-600"><?= $kategori['key'] === 'aktif' ? '—' : e((string) $kategori['days']) . ' hari' ?></td><td class="px-5 py-4 text-slate-600"><?= e($row['jenis_tindakan'] ?: '—') ?></td><td class="px-5 py-4 font-medium"><?= $row['biaya_tindakan'] !== null ? e(formatRupiah($row['biaya_tindakan'])) : '—' ?></td><td class="px-5 py-4"><?php if ($row['status_verifikasi']): ?><span class="badge badge-<?= strtolower($row['status_verifikasi']) ?>"><?= e($row['status_verifikasi']) ?></span><?php else: ?><span class="text-slate-500">Belum daftar</span><?php endif; ?></td><td class="px-5 py-4 font-medium"><?= $row['biaya_daftar_ulang'] !== null ? e(formatRupiah($row['biaya_daftar_ulang'])) : '—' ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: $emptyTitle='Laporan tidak memiliki data'; $emptyText='Sesuaikan filter atau tambahkan data pelanggan terlebih dahulu.'; require root_path('app/Views/components/empty-state.php'); endif; ?></div></section>
